<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Terms Consent</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f6f8fb;
        --surface: #ffffff;
        --text: #111827;
        --muted: #5b6472;
        --border: #cfd7e3;
        --border-strong: #8b98aa;
        --primary: #265df2;
        --primary-dark: #1746c8;
        --danger: #b42318;
        --success: #067647;
        --focus: #f59e0b;
        --shadow: 0 24px 70px rgba(15, 23, 42, 0.14);
      }

      * {
        box-sizing: border-box;
      }

      body {
        min-height: 100vh;
        margin: 0;
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top left, rgba(38, 93, 242, 0.14), transparent 32rem),
          linear-gradient(135deg, #f8fbff 0%, var(--bg) 58%, #eef3fb 100%);
      }

      a {
        color: var(--primary);
        font-weight: 700;
        text-underline-offset: 0.18em;
      }

      a:hover {
        color: var(--primary-dark);
      }

      a:focus-visible,
      button:focus-visible,
      input:focus-visible {
        outline: 3px solid var(--focus);
        outline-offset: 3px;
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 10;
        transform: translateY(-150%);
        border-radius: 999px;
        padding: 0.75rem 1rem;
        color: var(--text);
        background: var(--surface);
        box-shadow: var(--shadow);
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .page-shell {
        display: grid;
        min-height: 100vh;
        place-items: center;
        padding: 2rem 1rem;
      }

      main {
        width: min(100%, 32rem);
      }

      .card {
        overflow: hidden;
        border: 1px solid rgba(207, 215, 227, 0.9);
        border-radius: 1.5rem;
        background: rgba(255, 255, 255, 0.92);
        box-shadow: var(--shadow);
      }

      .card-header {
        padding: 2rem 2rem 1rem;
      }

      .eyebrow {
        margin: 0 0 0.75rem;
        color: var(--primary);
        font-size: 0.78rem;
        font-weight: 800;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 8vw, 3.25rem);
        line-height: 0.95;
        letter-spacing: -0.06em;
      }

      .intro {
        margin: 1rem 0 0;
        color: var(--muted);
        font-size: 1rem;
        line-height: 1.6;
      }

      form {
        padding: 1rem 2rem 2rem;
      }

      .required-note,
      .helper,
      .error,
      .status {
        font-size: 0.92rem;
        line-height: 1.5;
      }

      .required-note {
        margin: 0 0 1rem;
        color: var(--muted);
      }

      .form-field {
        display: grid;
        gap: 0.6rem;
        margin-bottom: 1.5rem;
      }

      .checkbox-row {
        display: grid;
        grid-template-columns: auto 1fr;
        gap: 0.85rem;
        align-items: start;
      }

      input[type="checkbox"] {
        width: 1.35rem;
        height: 1.35rem;
        margin: 0.15rem 0 0;
        accent-color: var(--primary);
        cursor: pointer;
      }

      label {
        font-weight: 750;
        line-height: 1.45;
        cursor: pointer;
      }

      .required-marker {
        color: var(--danger);
        font-weight: 900;
      }

      .helper {
        margin: 0 0 0 2.2rem;
        color: var(--muted);
      }

      .error {
        margin: 0 0 0 2.2rem;
        color: var(--danger);
        font-weight: 700;
      }

      [hidden] {
        display: none;
      }

      button {
        width: 100%;
        border: 0;
        border-radius: 999px;
        padding: 0.95rem 1.25rem;
        color: #ffffff;
        background: var(--primary);
        box-shadow: 0 12px 24px rgba(38, 93, 242, 0.24);
        font: inherit;
        font-weight: 800;
        cursor: pointer;
      }

      button:hover {
        background: var(--primary-dark);
      }

      button:active {
        transform: translateY(1px);
      }

      .status {
        min-height: 1.5rem;
        margin: 1rem 0 0;
        color: var(--success);
        font-weight: 700;
      }

      @media (max-width: 30rem) {
        .card-header,
        form {
          padding-left: 1.25rem;
          padding-right: 1.25rem;
        }

        .helper,
        .error {
          margin-left: 0;
        }
      }

      @media (forced-colors: active) {
        :root {
          --shadow: none;
        }

        .card,
        button,
        .skip-link {
          border: 1px solid CanvasText;
        }

        button {
          forced-color-adjust: none;
          color: ButtonText;
          background: ButtonFace;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main">Skip to main content</a>

    <div class="page-shell">
      <main id="main">
        <section class="card" aria-labelledby="page-title">
          <div class="card-header">
            <p class="eyebrow">Consent required</p>
            <h1 id="page-title">Review and continue</h1>
            <p class="intro">
              Confirm that you understand the product terms before submitting the form.
            </p>
          </div>

          <form id="consent-form" novalidate>
            <p class="required-note">
              Required fields are marked with <span class="required-marker" aria-hidden="true">*</span>.
            </p>

            <div class="form-field">
              <div class="checkbox-row">
                <input
                  id="terms"
                  name="terms"
                  type="checkbox"
                  required
                  aria-describedby="terms-helper terms-error"
                >
                <label for="terms">
                  I agree to the Terms of Use
                  <span class="required-marker" aria-hidden="true">*</span>
                </label>
              </div>
              <p id="terms-helper" class="helper">
                You must agree before this form can be submitted.
              </p>
              <p id="terms-error" class="error" hidden>
                Error: Agree to the Terms of Use to continue.
              </p>
            </div>

            <button type="submit">Accept and continue</button>
            <p id="form-status" class="status" aria-live="polite"></p>
          </form>
        </section>
      </main>
    </div>

    <script>
      const form = document.querySelector("#consent-form");
      const checkbox = document.querySelector("#terms");
      const error = document.querySelector("#terms-error");
      const status = document.querySelector("#form-status");

      function showError() {
        checkbox.setAttribute("aria-invalid", "true");
        error.hidden = false;
        status.textContent = "";
      }

      function clearError() {
        checkbox.removeAttribute("aria-invalid");
        error.hidden = true;
      }

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        if (!checkbox.checked) {
          showError();
          checkbox.focus();
          return;
        }

        clearError();
        status.textContent = "Thanks. Your consent has been recorded.";
        form.reset();
      });

      checkbox.addEventListener("change", () => {
        if (checkbox.checked) {
          clearError();
        }
      });
    </script>
  </body>
</html>
